const payload = items[0].json || {};
const msg = payload.message || payload.edited_message || payload.channel_post || {};
const from = msg.from || {};
const chat = msg.chat || {};
const text = msg.text || msg.caption || '';
const languageHint = /[äöüß]|\b(habe|zeige|termin|anhang|datei|e-mail)\b/i.test(text) ? 'de' : 'en';
return [{ json: { platform: 'telegram', telegramChatId: String(chat.id || ''), telegramUserId: String(from.id || ''), telegramUserName: from.username || [from.first_name, from.last_name].filter(Boolean).join(' '), telegramMessageId: msg.message_id || '', chatInput: String(text || '').trim(), messageType: msg.document ? 'document' : (msg.video ? 'video' : 'text'), languageHint, originalPayload: payload } }];

const input = items[0].json || {};
const raw = String($env.TELEGRAM_ALLOWED_CHAT_IDS || 'REPLACE_WITH_ALLOWED_TELEGRAM_CHAT_IDS');
const allowed = raw.split(',').map(v => v.trim()).filter(Boolean);
const authorized = allowed.includes(String(input.telegramChatId));
return [{ json: { ...input, authorized, allowedConfigured: !allowed.includes('REPLACE_WITH_ALLOWED_TELEGRAM_CHAT_IDS') } }];

const input = items[0].json || {};
if (input.error) return [{ json: { ...input, output: `Tool failed: Yes
Tool used: AI Agent Command Center
Error message: ${String(input.error.message || input.error).slice(0, 500)}
Action taken: No Microsoft 365 state was changed.
Verification status: Failed` } }];
return [{ json: input }];

const input = items[0].json || {};
let text = input.output || input.response || input.text || input.message || '';
if (typeof text !== 'string') text = JSON.stringify(text);
text = text.replace(/^=+\s*/, '');
text = text.replace(/\b(undefined|null)\b/gi, '').replace(/This message was sent automatically with n8n\.?/gi, '');
text = text.replace(/```json[\s\S]*?```/gi, '').replace(/\{\s*"debug"[\s\S]*?\}/gi, '');
text = text.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
if (!text) text = input.languageHint === 'de' ? 'Bitte formulieren Sie die Anfrage etwas genauer.' : 'Please clarify your request.';
return [{ json: { ...input, finalReply: text } }];

const input = items[0].json || {};
const max = 3900;
const lines = String(input.finalReply || '').split('\n');
const chunks = [];
let current = '';
for (const line of lines) {
  const addition = current ? '\n' + line : line;
  if ((current + addition).length > max && current) { chunks.push(current); current = line; } else { current += addition; }
}
if (current) chunks.push(current);
return chunks.map((chunk, index) => ({ json: { ...input, finalReply: chunk, replyPart: index + 1, replyParts: chunks.length } }));

const input = items[0].json || {};
console.log(JSON.stringify({ ts: new Date().toISOString(), chatId: input.telegramChatId, messageId: input.telegramMessageId, authorized: input.authorized, replyPart: input.replyPart || 1 }));
return [{ json: { logged: true, response: 'Execution logged', verificationStatus: 'Passed' } }];
